//! Protected acceptance: the raid audit read caps the cross-run log.
//!
//! Test Author-owned suite: do not edit this file to make it pass. Implement
//! the cap in `FileAudit::open` (`crates/cutover/src/raid_tools.rs`) instead.
//! This binary spawns nothing (see `raid_audit_lock.rs` for why audit tests
//! must not fork while an audit fd is open).
//!
//! Contract under test:
//!
//! * The append-only audit file `FileAudit::open` replays is capped at
//!   8 MiB, matching the capped cutover siblings (`raid-remove` refuses its
//!   target list with `target file exceeds 8 MiB`).
//! * An over-cap audit file is refused fail-closed: the error names the
//!   audit role and the `8 MiB` cap, in the existing repair-evidence style
//!   (`...; repair evidence before resuming`), and the lock is released so
//!   repaired evidence can resume.
//! * An audit file at exactly the cap opens: the boundary is strict `>`.
//! * Small valid audits replay exactly as today.
//!
//! Offline fixtures only: synthetic audit files under temp dirs. No DB, no
//! network, no Discord.

use two_bot_core::raid_removal::RemovalMode;
use two_bot_cutover::raid_tools::{FileAudit, RemovalOutcome, RemovalRecord};

/// The pinned cap: 8 MiB, matching the capped cutover siblings. Kept as a
/// literal here so the contract does not move with the implementation.
const CAP_BYTES: usize = 8 * 1024 * 1024;

const G: &str = "100000000000000010";
const A: &str = "100000000000000001";

fn scratch_path(name: &str) -> std::path::PathBuf {
    let root = std::env::var_os("PAPERCLIP_RUN_SCRATCH_DIR")
        .or_else(|| std::env::var_os("PAPERCLIP_SCRATCH_DIR"))
        .map(std::path::PathBuf::from)
        .unwrap_or_else(std::env::temp_dir);
    root.join(format!(
        "raid-audit-cap-{name}-{}-{}.jsonl",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ))
}

fn kicked_record() -> RemovalRecord {
    RemovalRecord {
        v: 1,
        ts: "2026-09-01T00:00:00Z".into(),
        run_id: "cap-fixture".into(),
        guild_id: G.into(),
        member_id: A.into(),
        mode: RemovalMode::Execute,
        action: "kick".into(),
        outcome: RemovalOutcome::Kicked,
        status: Some(204),
        attempts: 1,
    }
}

/// Over-cap contract: fail-closed refusal naming the audit role, the cap,
/// and the repair-evidence next step. The fixture is blank lines only, so
/// only the cap can refuse it (blank lines replay to an empty done set).
#[test]
fn over_cap_audit_open_is_refused_fail_closed() {
    let path = scratch_path("over");
    std::fs::write(&path, "\n".repeat(CAP_BYTES + 1)).unwrap();
    assert_eq!(
        std::fs::metadata(&path).unwrap().len() as usize,
        CAP_BYTES + 1
    );
    let err = FileAudit::open(&path, G)
        .err()
        .unwrap_or_else(|| panic!("over-cap audit file must be refused, not buffered whole"));
    assert!(
        err.contains("audit"),
        "refusal must name the audit role, got: {err:?}"
    );
    assert!(
        err.contains("8 MiB"),
        "refusal must name the 8 MiB cap, got: {err:?}"
    );
    assert!(
        err.contains("repair evidence"),
        "refusal must carry repair-evidence wording, got: {err:?}"
    );
    // Refusal must release the lock so repaired evidence can resume.
    std::fs::write(&path, "").unwrap();
    let audit = FileAudit::open(&path, G).unwrap();
    assert!(audit.done.is_empty());
    drop(audit);
    std::fs::remove_file(&path).unwrap();
}

/// At-cap contract: exactly 8 MiB opens and replays. One valid record plus
/// blank-line padding (blank lines are skipped by the replay).
#[test]
fn at_cap_audit_open_is_accepted() {
    let path = scratch_path("at");
    let line = serde_json::to_string(&kicked_record()).unwrap();
    let pad = CAP_BYTES.checked_sub(line.len() + 1).unwrap();
    let content = format!("{line}\n{}", "\n".repeat(pad));
    assert_eq!(content.len(), CAP_BYTES);
    std::fs::write(&path, &content).unwrap();
    let audit = FileAudit::open(&path, G).unwrap();
    assert!(
        audit.done.contains(A),
        "at-cap audit must replay the kicked member"
    );
    drop(audit);
    std::fs::remove_file(&path).unwrap();
}

/// Control: a small valid audit replays exactly as today, so a refusal
/// above is attributable to the cap and not to the fixture shape.
#[test]
fn small_valid_audit_replays_done_set() {
    let path = scratch_path("control");
    let mut executed = kicked_record();
    let dry = RemovalRecord {
        mode: RemovalMode::DryRun,
        outcome: RemovalOutcome::WouldKick,
        status: None,
        attempts: 0,
        ..kicked_record()
    };
    {
        let mut audit = FileAudit::open(&path, G).unwrap();
        audit.append(&executed).unwrap();
        audit.append(&dry).unwrap();
    }
    executed.member_id = "100000000000000002".into();
    {
        let mut audit = FileAudit::open(&path, G).unwrap();
        assert!(audit.done.contains(A));
        audit.append(&executed).unwrap();
    }
    let audit = FileAudit::open(&path, G).unwrap();
    assert!(audit.done.contains(A));
    assert!(audit.done.contains("100000000000000002"));
    drop(audit);
    std::fs::remove_file(&path).unwrap();
}
